-- =====================================================================
--  Prime Script — Contenu prêt à l'emploi (5/12) : Questions de découverte (service, secteur, étape)
--
--  Ce fichier s'importe avec les autres fichiers de database/content/ :
--      php tools/import-content.php
--  (ou, en MySQL : mysql -u ... prime_script < database/content/content.sql
--   si ce fichier a été concaténé dans content.sql).
--
--  Format d'une ligne de contenu (JSON, une ligne par enregistrement) :
--    {"code": "...", "type": "...", "sector": "...", "stage": "...",
--     "service": "...", "title": "...", "position": 10, "content": "<p>…</p>"}
--
--    code     identifiant stable du bloc (réimport = mise à jour, jamais de doublon)
--    type     presentation | accroche | barrage | repondeur | decouverte |
--             argumentaire | preuve | tarif | appel_action | conclusion
--    sector   slug du secteur (architectes, artisans-btp, restauration, services-b2b)
--    stage    slug de l'étape (premier-appel, relance, closing)
--    service  slug du service (site-web, application, automatisation-ia, chatbot-ia)
--    content  HTML simple : <p>, <ul>, <li>, <strong>, <em>
--
--  Convention d'écriture : le texte à dire est en clair, l'aide au commercial
--  est sur une ligne « Conseil : … » en italique (<p><em>Conseil : …</em></p>).
-- =====================================================================

SET NAMES utf8mb4;

{"code": "dec-site-web-1", "type": "decouverte", "service": "site-web", "title": "Site web — les questions, dans l'ordre", "content": "<p>Posez-les dans cet ordre, puis arrêtez-vous : quatre bonnes réponses suffisent pour proposer.</p><ul><li>Aujourd'hui, comment vos clients vous trouvent-ils ?<br><em>Conseil : vous saurez si le site est un canal réel ou un simple panneau.</em></li><li>Quand quelqu'un vous cherche sur Google, il tombe sur quoi ?<br><em>Conseil : c'est la question qui révèle le problème le plus fréquent : un site absent ou daté.</em></li><li>Qu'est-ce qui manque le plus à votre site actuel ?<br><em>Conseil : laissez le prospect formuler le besoin. Vous n'aurez pas à le convaincre.</em></li><li>Combien de demandes recevez-vous par mois, à peu près ?<br><em>Conseil : un ordre de grandeur suffit, pas un chiffre exact.</em></li><li>Qui met à jour les textes et les photos, aujourd'hui ?<br><em>Conseil : si c'est un prestataire, le client est dépendant. C'est un point de douleur.</em></li><li>Sur téléphone, votre site s'affiche bien ?<br><em>Conseil : beaucoup répondent « je crois ». Proposez de regarder ensemble, c'est parlant.</em></li><li>Si vous refaisiez le site, qu'est-ce qui changerait pour vous ?<br><em>Conseil : la réponse donne le vrai critère de décision : plus de demandes, plus de crédibilité, ou du temps.</em></li></ul>"}
{"code": "dec-application-1", "type": "decouverte", "service": "application", "title": "Application sur mesure — les questions, dans l'ordre", "content": "<p>Ici, on cherche surtout le processus manuel qui coûte du temps. Écoutez les mots du métier.</p><ul><li>Comment vous organisez-vous aujourd'hui : tableur, cahier, logiciel ?<br><em>Conseil : c'est le point de départ réel de tout projet d'application.</em></li><li>Combien de tableurs différents utilisez-vous, à peu près ?<br><em>Conseil : plus il y en a, plus la douleur est facile à montrer.</em></li><li>Qui doit voir les informations, et qui ne doit pas ?<br><em>Conseil : les droits d'accès font partie du besoin, même si le client n'y pense pas.</em></li><li>Quelle tâche refaites-vous plusieurs fois par jour ?<br><em>Conseil : c'est là que se trouve le gain de temps le plus visible.</em></li><li>Ça vous arrive de ressaisir la même information deux fois ?<br><em>Conseil : question simple, réponse presque toujours oui. Elle fait mouche.</em></li><li>Avez-vous un outil que vous devez garder absolument ?<br><em>Conseil : comptabilité, caisse, CRM. Cela conditionne les connexions à prévoir.</em></li><li>Sur téléphone, tablette ou ordinateur : où travaillez-vous le plus ?<br><em>Conseil : une application terrain et une application de bureau ne se conçoivent pas pareil.</em></li><li>Si vous gagniez une heure par jour, qu'est-ce que vous en feriez ?<br><em>Conseil : la réponse relie le projet à un bénéfice concret, pas à de l'informatique.</em></li></ul>"}
{"code": "dec-automatisation-ia-1", "type": "decouverte", "service": "automatisation-ia", "title": "Automatisation IA — les questions, dans l'ordre", "content": "<p>L'objectif est de trouver UNE tâche répétitive, pas de cartographier toute l'entreprise.</p><ul><li>Quelles tâches vous prennent le plus de temps chaque semaine ?<br><em>Conseil : notez-les telles quelles, avec les mots du client.</em></li><li>Combien de demandes arrivent par mail, formulaire ou téléphone ?<br><em>Conseil : le volume justifie l'automatisation. Sans volume, rien ne se rentabilise.</em></li><li>Qui traite ces demandes, et à quel moment de la journée ?<br><em>Conseil : vous découvrez souvent que tout repose sur une seule personne.</em></li><li>Que se passe-t-il si une demande attend 48 heures ?<br><em>Conseil : la réponse chiffre le coût de l'inaction, sans que vous ayez à l'inventer.</em></li><li>Quelles informations recopiez-vous d'un outil à l'autre ?<br><em>Conseil : c'est le candidat idéal pour une première automatisation simple.</em></li><li>Qui doit valider avant qu'un message part ?<br><em>Conseil : le client a besoin d'un contrôle humain. Proposez-le avant qu'il le demande.</em></li><li>Avez-vous déjà essayé d'automatiser quelque chose ? Qu'est-ce qui a bloqué ?<br><em>Conseil : un échec passé explique souvent une méfiance. Il faut l'entendre.</em></li></ul>"}
{"code": "dec-chatbot-ia-1", "type": "decouverte", "service": "chatbot-ia", "title": "Chatbot IA — les questions, dans l'ordre", "content": "<p>Le chatbot se vend sur les questions qui reviennent, pas sur la technologie.</p><ul><li>Quelles questions reviennent le plus souvent de la part de vos clients ?<br><em>Conseil : trois ou quatre questions suffisent à construire un premier assistant utile.</em></li><li>Combien d'appels par jour pour ces questions-là ?<br><em>Conseil : c'est le temps que l'assistant rendra à l'équipe.</em></li><li>Que se passe-t-il le soir et le week-end, quand vous êtes fermé ?<br><em>Conseil : chaque message sans réponse est une demande perdue, sans que vous ayez à la chiffrer.</em></li><li>Qui répond aux messages du site aujourd'hui ?<br><em>Conseil : souvent personne. C'est l'argument le plus simple du chatbot.</em></li><li>Sur quelles informations l'assistant peut-il s'appuyer sans se tromper ?<br><em>Conseil : horaires, tarifs de départ, zone d'intervention : il ne répondra qu'à ça.</em></li><li>Quand un client doit-il parler à un humain, selon vous ?<br><em>Conseil : vous préparez la règle de passage à l'humain avec le client lui-même.</em></li><li>Ça vous gênerait qu'un assistant réponde la nuit à votre place ?<br><em>Conseil : posez la question franchement. La réponse dit si le projet est mûr.</em></li></ul>"}
{"code": "dec-architectes-1", "type": "decouverte", "service": null, "title": "Questions propres aux architectes et bureaux d'études", "content": "<p>Trois questions pour entrer dans le quotidien d'une agence.</p><ul><li>Combien de projets en cours avez-vous en ce moment ?<br><em>Conseil : un architecte jauge sa charge en projets, pas en mois. Parlez son langage.</em></li><li>Où sont vos réalisations aujourd'hui : site, Instagram, PDF ?<br><em>Conseil : c'est la première question à laquelle un projet de site répond.</em></li><li>Sur un dossier, combien de temps passez-vous à chercher des documents ?<br><em>Conseil : une agence qui perd du temps sur les plans est un client pour un espace projet.</em></li></ul>", "sector": "architectes"}
{"code": "dec-artisans-btp-1", "type": "decouverte", "service": null, "title": "Questions propres aux artisans et au BTP", "content": "<p>Trois questions pour parler chantier, sans jargon.</p><ul><li>Combien de demandes de devis par semaine, et en combien de temps vous y répondez ?<br><em>Conseil : le délai de réponse est le premier facteur de signature dans ce métier.</em></li><li>Vous relancez les devis qui n'ont pas de réponse ?<br><em>Conseil : la plupart ne relancent pas, faute de temps. C'est le sujet à travailler.</em></li><li>Vous travaillez dans un rayon de combien de kilomètres ?<br><em>Conseil : la zone d'intervention détermine les pages et le référencement local à prévoir.</em></li></ul>", "sector": "artisans-btp"}
{"code": "dec-restauration-1", "type": "decouverte", "service": null, "title": "Questions propres aux restaurants", "content": "<p>Trois questions à poser hors service, jamais à midi.</p><ul><li>Combien d'appels par jour pour des réservations ?<br><em>Conseil : c'est le volume que la réservation en ligne ou l'assistant peuvent absorber.</em></li><li>Combien de couverts par service en moyenne ?<br><em>Conseil : un restaurant qui remplit déjà ne cherche pas plus de clients, mais moins de travail.</em></li><li>Votre carte en ligne, elle est à jour ?<br><em>Conseil : un client qui trouve une carte périmée part souvent. Le sujet est très concret.</em></li></ul>", "sector": "restauration"}
{"code": "dec-services-b2b-1", "type": "decouverte", "service": null, "title": "Questions propres aux services B2B", "content": "<p>Trois questions pour qualifier vite un dossier.</p><ul><li>Combien de rendez-vous qualifiés par mois ?<br><em>Conseil : c'est la mesure qui compte pour une entreprise de services.</em></li><li>Combien de temps entre le premier contact et la signature ?<br><em>Conseil : un cycle long demande des relances. Un cycle court demande un site qui convertit.</em></li><li>Qui suit les devis, et avec quel outil ?<br><em>Conseil : un suivi dans une boîte mail est un signal d'automatisation.</em></li></ul>", "sector": "services-b2b"}
{"code": "dec-relance-1", "type": "decouverte", "service": null, "title": "Découverte — en relance", "content": "<p>En relance, on ne redécouvre pas : on précise ce qui bloque.</p><ul><li>Est-ce que le devis correspond à ce que vous attendiez ?<br><em>Conseil : si la réponse est non, tout le reste de l'appel porte sur l'écart.</em></li><li>Qu'est-ce qui vous freine encore : le budget, le délai, la technique ?<br><em>Conseil : en proposant trois pistes, vous obtenez la vraie plus vite.</em></li><li>Qui d'autre doit valider, et quand peut-on l'inclure ?<br><em>Conseil : tant que le décideur n'est pas là, la relance tourne en rond.</em></li><li>Si on commence la semaine prochaine, c'est jouable ?<br><em>Conseil : une question de calendrier révèle plus qu'une question de motivation.</em></li></ul>", "stage": "relance"}
{"code": "dec-closing-1", "type": "decouverte", "service": null, "title": "Découverte — en closing", "content": "<p>Trois questions maximum. Au closing, on ne découvre plus, on verrouille.</p><ul><li>Reste-t-il un point qui vous empêche de signer aujourd'hui ?<br><em>Conseil : la question est directe. Elle fait gagner deux appels.</em></li><li>Le montant du devis est-il validé de votre côté ?<br><em>Conseil : ne supposez jamais que le budget est acquis.</em></li><li>On cale le démarrage sur quelle date ?<br><em>Conseil : une date dans la conversation vaut mieux qu'une date dans un mail.</em></li></ul>", "stage": "closing"}
